// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCandidate, address caller) public {
        // 1. admissible: ownerCandidate != address(0) && ownerCandidate != caller
        vm.assume(ownerCandidate != address(0));
        vm.assume(ownerCandidate != caller);

        // 2. set the contract's owner to ownerCandidate by calling initialize
        //    initialize sets the owner to msg.sender; we prank as ownerCandidate.
        vm.prank(ownerCandidate);
        c.initialize(0, 0, "", ownerCandidate);

        // 3. now call owner() as a different address (caller)
        vm.prank(caller);
        address returnedOwner = c.owner();

        // 4. the reference always returns the stored owner (ownerCandidate);
        //    the bug returns msg.sender (caller).
        assertTrue(returnedOwner == ownerCandidate);
    }
}

