pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != newOwner);
        vm.prank(newOwner);
        c.acceptOwnership();
        vm.prank(caller);
        address observed = c.owner();
        assertTrue(observed == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize(1, 1, "test", address(this));
    }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        vm.assume(caller1 != address(c));
        vm.assume(caller2 != address(c));

        vm.prank(caller1);
        address ownerSeenByCaller1 = c.owner();

        vm.prank(caller2);
        address ownerSeenByCaller2 = c.owner();

        assertTrue(ownerSeenByCaller1 == ownerSeenByCaller2, "owner() should be independent of caller");
    }
}
